import csv
cols=["row_id","class","population","context","factor","reported_value","proposed_distribution","basis","source","url","notes"]
R=[]
def r(**k): R.append(k)
MA="https://www.frontiersin.org/journals/marine-science/articles/10.3389/fmars.2022.897298/full"; RB="(user PDF) Rankin & Barlow 2005"
GE="(user PDF) Gedamke et al. 2001"; RI="https://epic2-clone.awi.de/35450/1/BiolLett-2014-Risch-.pdf"; DO="https://www.cetus.ucsd.edu/docs/publications/DominelloMMS2016.pdf"
NT="https://mersociety.org/wp-content/uploads/2023/11/nikolich-and-towers.pdf"
M="Minke"
r(**{"class":M},population="all",context="all",factor="Context balance",reported_value="N Pacific boing (nominal and rapid calling), BC feeding downsweeps, dwarf minke star-wars bouts, Antarctic bio-duck, Antarctic downsweeps",proposed_distribution="EQUAL encounters per context: boing-nominal, boing-rapid, BC downsweep, dwarf star-wars, Antarctic bio-duck, Antarctic downsweep",basis="design rule",source="-",url="",notes="boing nominal vs rapid kept as separate contexts so both are equally represented")
r(**{"class":M},population="N Pacific (Kauai)",context="Boing",factor="Calling states",reported_value="ICI bimodal: state 1 6.85+-2.54 min (8.7 calls/h), state 2 0.63+-0.36 min (95.2 calls/h); 91% of time in state 1, 9% in state 2; rapid calling more likely when a calling neighbour is closer (within ~7-12 km)",proposed_distribution="boing-nominal: ICI ~ N(6.85, 2.54) min; boing-rapid: ICI ~ N(0.63, 0.36) min with a 2nd caller 1-12 km away; switching between states allowed within encounter",basis="literature",source="Martin et al. 2022",url=MA)
r(**{"class":M},population="N Pacific (Kauai)",context="Boing",factor="Calls per track / silences",reported_value="509 focal tracks, ~71 calls per track (36,033 calls); tracks end after >=40 min silence; examples: pauses of 15 and 36 min when neighbours approached; calling stopped when neighbour within 900 m; boings Oct-May only",proposed_distribution="calling spells of 20-150 calls; silences lognormal median 20 min (5-60); encounter can end with mutual silence",basis="literature + assumed silence distribution",source="Martin et al. 2022",url=MA)
r(**{"class":M},population="N Pacific",context="Boing",factor="Individual vs population",reported_value="one whale: PRR 114.3+-0.8 /s, duration 2.0+-0.5 s (n=84) vs population 115.0+-1.3 /s, 2.6+-0.4 s",proposed_distribution="per-caller PRR SD ~0.6 x population SD; duration SD similar to population",basis="literature",source="Rankin & Barlow 2005",url=RB)
r(**{"class":M},population="N Pacific (BC feeding)",context="Downsweep",factor="Call rate",reported_value="0.030 calls/min (~1.8-2.8 calls/h; paper inconsistent); downsweeps rare (n=4) vs pulse chains",proposed_distribution="downsweep encounters: rate lognormal median 2/h (0.5-10); long silences",basis="literature",source="Nikolich & Towers 2018",url=NT)
r(**{"class":M},population="Dwarf minke (GBR)",context="Star-wars",factor="Bouts and repetition",reported_value="49 encounters; groups of 1 to >=10 circling vessel; bouts of 7, 10, 8 min containing 13, 18, 15 SW sequences, ~32-33 s apart (32.0+-1.6); sequence interval 1-2 s to 3-4 min; C unit truncated/absent during rapid vocal activity; downsweeps in 59% of encounters",proposed_distribution="bouts lognormal median 8 min with SW every ~32 s (+-1.6 within bout); silences between bouts lognormal median 10 min (assumed); 1-3 callers; 60% of SW encounters also include downsweeps",basis="literature + assumed silence",source="Gedamke et al. 2001",url=GE)
r(**{"class":M},population="Antarctic minke (WAP)",context="Bio-duck",factor="Presence / bouts",reported_value="bio-duck 22.8% of recorded time Jun-Oct (peak Jul), linked to >50% sea ice; series every 1.7-5.1 s (variant-specific); downsweeps 2.8% of time",proposed_distribution="bio-duck encounters: long bouts lognormal median 1 h of series every ~3 s, silences lognormal median 30 min (assumed); variant (A1/A2/B/C/D) drawn per encounter, 1-2 variants",basis="literature + assumed bout/silence",source="Dominello & Sirovic 2016; Risch et al. 2014",url=DO)
r(**{"class":M},population="Antarctic minke",context="Bio-duck",factor="Regional pulse count",reported_value="~3 pulses/burst (Ross Sea, Dumont d'Urville) vs 5-6 (W Antarctica); tags 7+-3 (5-12)",proposed_distribution="pulses per series drawn per encounter by region",basis="literature",source="Risch et al. 2014",url=RI)
r(**{"class":M},population="Antarctic minke",context="Downsweep",factor="Rate",reported_value="downsweeps 2.8% of time; single calls",proposed_distribution="rate lognormal median 5/h (1-30) (assumed); irregular",basis="assumed rate",source="Dominello & Sirovic 2016",url=DO)
r(**{"class":M},population="all",context="all",factor="Range / detectability",reported_value="boing tracks localised across a 20x60 km range; dwarf minkes recorded within 20-30 m",proposed_distribution="boing range 1-30 km; dwarf 0.02-5 km; bio-duck 1-50 km -> completeness/fragmentation; star-wars upper harmonics above 4 kHz ignored",basis="literature + assumed",source="Martin 2022; Gedamke 2001",url=MA)
r(**{"class":M},population="all",context="Chorus",factor="Chorus",reported_value="bio-duck can dominate Antarctic winter soundscapes (multiple distant callers implied by high % time); not quantified as chorus",proposed_distribution="bio-duck encounters: distant-caller layer p = 0.3 (assumed); none for other contexts",basis="assumed",source="Dominello & Sirovic 2016",url=DO)
B="Brydes"
HB="https://www.frontiersin.org/journals/marine-science/articles/10.3389/fmars.2024.1305505/pdf"; HE="(user PDF) Heimlich et al. 2005"; OL="https://www.cetus.ucsd.edu/docs/publications/OlesonMMS2003.pdf"; VG="(user PDF) Viloria-Gomora et al. 2015"
r(**{"class":B},population="all",context="all",factor="Context balance",reported_value="regional call types; lone-whale calls (Be2, Be5) vs group calls (Be1); Be4 with 2+ animals; repetitive series",proposed_distribution="EQUAL encounters per region x phrase-type context (ETP 5 phrase types + Be4-Be6, Gulf of California, Kauai Be3, Japan Be8, NZ)",basis="design rule",source="-",url="")
r(**{"class":B},population="Central N Pacific (Kauai)",context="Be3-type",factor="Calls per track / rate / ICI",reported_value="150 tracks, ~40 calls per track; example tracks ~6-18 h; ICI median 306 s (mean 361); cue rate median 22/h (IQR 15-39); calls about once per 5 min; breaks at surfacing; track ends after 40 min silence",proposed_distribution="ICI lognormal median 5 min (2.5-10 min); encounter spells of 10-100 calls over 1-18 h; occasional silences 10-40 min (assumed)",basis="literature",source="Helble et al. 2024",url=HB)
r(**{"class":B},population="Central N Pacific",context="Be3-type",factor="Movement / multiple callers",reported_value="speed 1.7+-0.7 m/s; slow (1.0 m/s, 66%) vs faster (2.1 m/s, 34%) states, slow more at night; multiple whales sometimes called simultaneously (32 tracks excluded for ambiguity)",proposed_distribution="1 caller (0.8) or 2 (0.2); range drift from 1.0-2.1 m/s movement",basis="literature",source="Helble 2024",url=HB)
r(**{"class":B},population="Eastern tropical Pacific",context="Phrase series",factor="Series and repetitions",reported_value="phrases occur in extended irregular series over several hours; interphrase 2.9-3.0 min (alternating tonal) or 3.9-6.3 s (burst-tonal, harmonic); repetitions of tones 3.3-4.3 s apart in 22-76% of phrases with decreasing amplitude; site and season strongly affect which phrase types occur",proposed_distribution="series of phrases for 0.5-6 h with reported interphrase intervals; repetition present with reported per-type probability",basis="literature",source="Heimlich et al. 2005",url=HE)
r(**{"class":B},population="Eastern tropical Pacific",context="Group vs lone",factor="Callers",reported_value="Be1 recorded from groups; Be2 and Be5 from lone whales; ICIs Be1 1.25 min ... Be5 5.5 min",proposed_distribution="Be1 context: 2-4 animals, 1-2 callers; Be2/Be5: 1 animal",basis="literature",source="Oleson et al. 2003",url=OL)
r(**{"class":B},population="Gulf of California",context="Be4 / Be10-12",factor="Calling fraction and group",reported_value="vocalisations in 3.46 of 11.8 h with whales (29.3%); almost all from solitary adults; none when calves present; Be4 from 21 animals when 2+ whales in area; Be10 possibly feeding",proposed_distribution="encounters: calling 30% of time (spells + silences); Be4 context 2+ animals; Be10-12 lone whale",basis="literature",source="Viloria-Gomora et al. 2015",url=VG)
r(**{"class":B},population="all",context="all",factor="Individual vs population",reported_value="not reported (frequencies very stereotyped: SDs 0.5-1.6 Hz)",proposed_distribution="within-caller SD 0.3 x population SD (assumed)",basis="assumed",source="-",url="")
r(**{"class":B},population="all",context="all",factor="Range / detectability",reported_value="ETP hydrophone detections over large areas; repeated tones decay in amplitude",proposed_distribution="range log-uniform 1-100 km -> completeness/fragmentation; secondary tones and harmonics drop out first",basis="assumed",source="Heimlich 2005",url=HE)
r(**{"class":B},population="all",context="Chorus",factor="Chorus",reported_value="none reported",proposed_distribution="no chorus layer",basis="literature (absence)",source="-",url="")
for prefix,cls in (("MKX","Minke"),("BWX","Brydes")):
    rows=[x for x in R if x["class"]==cls]
    for i,x in enumerate(rows,1): x["row_id"]=f"{prefix}{i:02d}"
    fn=f"encounter_context_{cls.lower()}.csv"
    with open(fn,"w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=cols); w.writeheader(); [w.writerow({c:x.get(c,"") for c in cols}) for x in rows]
    print(fn,len(rows))
